from ...adapters.soap import SoapAdapter


class CmDataRepositorySoapAdapter(SoapAdapter):

    def __init__(self, web_url, username, password):
        wsdl_url = (f'https://{web_url}/netact/cm/open-api/persistency/OpenCmPersistencyServiceSOAP'
                    f'/WEB-INF/wsdl/OpenCmPersistencyService.wsdl')
        super().__init__(wsdl_url, username, password)

    @property
    def common_type_factory(self):
        """
        :rtype: zeep.client.Factory
        """
        return self.client.type_factory('ns0')

    @property
    def metadata_type_factory(self):
        """
        :rtype: zeep.client.Factory
        """
        return self.client.type_factory('ns1')

    @property
    def model_type_factory(self):
        """
        :rtype: zeep.client.Factory
        """
        return self.client.type_factory('ns2')

    @property
    def query_type_factory(self):
        """
        :rtype: zeep.client.Factory
        """
        return self.client.type_factory('ns3')

    @property
    def operations_type_factory(self):
        """
        :rtype: zeep.client.Factory
        """
        return self.client.type_factory('ns4')
